  let r = length(d);
  let theta = r / (a - b * r);
  let lateral = select(0.0, sin(theta) / r, r > 1e-4);
  let body = vec3f(cos(theta), d.x * lateral, d.y * lateral);
  let local = vec3f(dot(frame.rowNorth.xyz, body), dot(frame.rowEast.xyz, body), dot(frame.rowDown.xyz, body));
